function estimateCategoryRank(air, category, stateRank) {
  const sRank = stateRank || estimateStateRank(air);
  
  if (snoToCatRanks2026[sRank] && snoToCatRanks2026[sRank].ranks) {
    const ranks = snoToCatRanks2026[sRank].ranks;
    let normCat = category.replace('-', '').replace('_', '');
    if (normCat === 'OPEN') normCat = 'OC';
    if (ranks[normCat]) return ranks[normCat];
    if (ranks['OC']) return ranks['OC']; 
  }

  const stateCatRatios = {
    OC: 0.35, EWS: 0.10, BC_A: 0.07, BC_B: 0.18,
    BC_C: 0.01, BC_D: 0.16, BC_E: 0.04, SC_1: 0.117, SC_2: 0.117, SC_3: 0.117, SC: 0.117, ST: 0.08
  };
  return Math.max(1, Math.round(sRank * (stateCatRatios[category] || 0.117)));
}

function computeAdjustedCatRanks() {
  let cumulativeGovtSeats = 0;
  let cumulativePvtSeats = 0;
  
  const stateCatRatios = {
    OC: 0.35, EWS: 0.10, BC_A: 0.07, BC_B: 0.18,
    BC_C: 0.01, BC_D: 0.16, BC_E: 0.04, SC_1: 0.117, SC_2: 0.117, SC_3: 0.117, SC: 0.117, ST: 0.08
  };

  govtColleges.forEach(c => {
    cumulativeGovtSeats += (c.seatsIncreased || 0);
    c.adjustedCatRanks = { ...c.knownCatRanks };
    for (let cat in c.knownCatRanks) {
      if (c.knownCatRanks[cat] !== 9999999) {
        c.adjustedCatRanks[cat] = c.knownCatRanks[cat] + Math.round(cumulativeGovtSeats * (stateCatRatios[cat] || 0.117));
      }
    }
  });

  pvtColleges.forEach(c => {
    cumulativePvtSeats += (c.seatsIncreased || 0);
    c.adjustedCatRanks = { ...c.knownCatRanks };
    for (let cat in c.knownCatRanks) {
      if (c.knownCatRanks[cat] !== 9999999) {
        c.adjustedCatRanks[cat] = c.knownCatRanks[cat] + Math.round((cumulativeGovtSeats + cumulativePvtSeats) * (stateCatRatios[cat] || 0.117));
      }
    }
  });
}
computeAdjustedCatRanks();

function getClosingRank(college, category) {
  // Normalize category to match knownCatRanks keys (e.g. BC_A, SC_2)
  let searchCat = category;
  if (searchCat === 'OPEN' || searchCat === 'OC') searchCat = 'OC';
  else if (searchCat.length === 3 && (searchCat.startsWith('BC') || searchCat.startsWith('SC'))) {
    searchCat = searchCat.substring(0, 2) + '_' + searchCat.substring(2);
  }

  if (college.adjustedCatRanks && college.adjustedCatRanks[searchCat] !== undefined) {
    return college.adjustedCatRanks[searchCat];
  }
  if (college.adjustedCatRanks && college.adjustedCatRanks['SC'] !== undefined && searchCat.startsWith('SC')) {
    return college.adjustedCatRanks['SC'];
  }
  
  const ocRank = (college.adjustedCatRanks && college.adjustedCatRanks['OC']) ? college.adjustedCatRanks['OC'] : (college.ocClosingCatRank || 9999999);
  const stateCatRatios = {
    OC: 0.35, EWS: 0.10, BC_A: 0.07, BC_B: 0.18,
    BC_C: 0.01, BC_D: 0.16, BC_E: 0.04, SC_1: 0.15, SC_2: 0.15, SC_3: 0.15, SC: 0.15, ST: 0.10
  };
  return Math.round(ocRank * (stateCatRatios[category] || 0.15) / 0.35);
}

function isEligible(rank, college, category) {
  const catRank = estimateCategoryRank(rank, category);
  const closing = getClosingRank(college, category);
  return catRank <= closing;
}

function runAllocation(rank, category, preferences) {
  for (let i = 0; i < preferences.length; i++) {
    const college = preferences[i];
    if (isEligible(rank, college, category)) {
      return { allocated: true, college: college, preferenceNo: i + 1, closingRank: getClosingRank(college, category) };
    }
  }
  return { allocated: false, college: null, preferenceNo: -1 };
}

function scoreToPercentile(score) {
  // NEET 2025: ~22.09 lakh appeared, rank-based percentile
  const rank = estimateRank(score);
  const total = 2209000;
  return Math.max(0, Math.min(100, ((total - rank) / total * 100))).toFixed(2);
}

function formatRank(rank) {
  if (rank >= 100000) return (rank / 100000).toFixed(1) + 'L';
  if (rank >= 1000) return (rank / 1000).toFixed(1) + 'K';
  return rank.toString();
}

function formatFee(fee) {
  if (fee >= 100000) return '₹' + (fee / 100000).toFixed(1) + 'L';
  if (fee >= 1000) return '₹' + (fee / 1000).toFixed(0) + 'K';
  return '₹' + fee;
}

function formatFeeExact(fee) {
  return '₹' + fee.toLocaleString('en-IN');
}

// ============================================================
// APPLICATION STATE
// ============================================================

let currentStep = 1;
let studentProfile = {};
let estimatedAIR = 0;
let preferences = [];
let collegeFilter = 'all';
let searchQuery = '';

// ============================================================
// UI FUNCTIONS
// ============================================================

let sortStrategy = 'categorized';

function buildPreferences(mode = 'categorized') {
  sortStrategy = mode;
  const gList = govtColleges.map(c => ({ ...c, type: 'govt' }));
  const pList = pvtColleges.map(c => ({ ...c, type: 'pvt' }));
  
  if (mode === 'mixed') {
    // Combined ranking sorted strictly by closing rank / cutoff score
    const combined = [...gList, ...pList];
    combined.sort((a, b) => (a.ocClosing || 999999) - (b.ocClosing || 999999));
    return combined;
  }

  if (mode === 'research') {
    // Research-based Master Mixed Order
    const combined = [...gList, ...pList];
    combined.sort((a, b) => {
      let idxA = masterCollegesData.findIndex(m => a.name.toLowerCase().includes(m.name.toLowerCase().split(' ')[0]) || m.name.toLowerCase().includes(a.name.toLowerCase().split(' ')[0]));
      let idxB = masterCollegesData.findIndex(m => b.name.toLowerCase().includes(m.name.toLowerCase().split(' ')[0]) || m.name.toLowerCase().includes(b.name.toLowerCase().split(' ')[0]));
      if (idxA === -1) idxA = 999;
      if (idxB === -1) idxB = 999;
      return idxA - idxB;
    });
    return combined;
  }

  // Categorized (Default):
  // 1. Top Govt Colleges (sorted by closing rank)
  // 2. Top Non-Minority Private Colleges (sorted by closing rank)
  // 3. Minority Private Colleges at the very end
  const gSorted = [...gList].sort((a, b) => (a.ocClosing || 999999) - (b.ocClosing || 999999));
  const pNonMinority = pList.filter(c => !c.name.includes('(Minority)')).sort((a, b) => (a.ocClosing || 999999) - (b.ocClosing || 999999));
  const pMinority = pList.filter(c => c.name.includes('(Minority)')).sort((a, b) => (a.ocClosing || 999999) - (b.ocClosing || 999999));

  return [...gSorted, ...pNonMinority, ...pMinority];
}

function changeSortMode(mode) {
  preferences = buildPreferences(mode);
  toggleCollegeList(true);
  renderCollegeList();
  showToast(
    mode === 'research' ? 'Sorted by Master Research Order (Govt + Pvt Mixed)' :
    mode === 'mixed' ? 'Sorted by Combined Cutoff Rank (Mixed)' :
    'Sorted by Categorized (Govt ➔ Pvt ➔ Minority)',
    'info'
  );
}

let isCollegeListVisible = false;

function toggleCollegeList(forceShow = false) {
  const container = document.getElementById('collegeList');
  const btn = document.getElementById('toggleCollegeListBtn');
  if (!container || !btn) return;

  if (forceShow) {
    isCollegeListVisible = true;
  } else {
    isCollegeListVisible = !isCollegeListVisible;
  }

  if (isCollegeListVisible) {
    container.style.display = 'flex';
    btn.innerHTML = '🙈 Hide College List';
    btn.style.borderColor = '#fbbf24';
    btn.style.color = '#fbbf24';
  } else {
    container.style.display = 'none';
    btn.innerHTML = '👁️ Show / Reorder College List';
    btn.style.borderColor = 'var(--accent-teal)';
    btn.style.color = 'var(--accent-teal)';
  }
}

let lastAllocatedResult = null;

function getSummaryText() {
  const { name, score, category, customAIR, customStateRank } = studentProfile;
  const air = customAIR || estimatedAIR;
  const stateRank = customStateRank || estimateStateRank(air);
  const catRank = estimateCategoryRank(air, category, stateRank);

  let govtEligible = 0, pvtEligible = 0;
  govtColleges.forEach(c => { if (isEligible(air, c, category)) govtEligible++; });
  pvtColleges.forEach(c => { if (isEligible(air, c, category)) pvtEligible++; });

  const catLabel = reservationData[category]?.label || category;

  let allocHeader = '';
  if (lastAllocatedResult && lastAllocatedResult.allocated && currentStep === 4) {
    const c = lastAllocatedResult.college;
    const isGovt = c.type === 'govt';
    const feeStr = formatFeeExact(isGovt ? c.fee : c.feeA);
    allocHeader =
      `🎉 *MOCK SEAT ALLOCATION RESULT*\n` +
      `🏫 *Allocated College:* ${c.name} (${c.place})\n` +
      `📌 *Preference Rank:* #${lastAllocatedResult.preferenceNo} in Web Options\n` +
      `🏛️ *College Type:* ${isGovt ? 'Government' : 'Private Cat-A (Convener Quota)'}\n` +
      `💰 *Annual Fee:* ${feeStr}/year\n` +
      `📈 *Est. Closing Rank:* ${lastAllocatedResult.closingRank.toLocaleString('en-IN')}\n\n`;
  }

  return `⚕️ *MSeat — Telangana MBBS Mock Counselling 2026*\n\n` +
    allocHeader +
    `👤 *Candidate:* ${name || 'Student'}\n` +
    `🎯 *NEET Score:* ${score || '469'} / 720\n` +
    `🏆 *All India Rank (AIR):* ${air ? air.toLocaleString('en-IN') : '1,34,093'}\n` +
    `📍 *Telangana State S.No:* ${stateRank ? stateRank.toLocaleString('en-IN') : '2,363'}\n` +
    `🏷️ *Category Rank (${catLabel}):* #${catRank ? catRank.toLocaleString('en-IN') : '276'}\n\n` +
    `📊 *Seat Eligibility Overview:*\n` +
    `• Government Colleges Eligible: ${govtEligible} / ${govtColleges.length}\n` +
    `• Private Cat-A Colleges Eligible: ${pvtEligible} / ${pvtColleges.length}\n` +
    `• Total Eligible Options: ${govtEligible + pvtEligible}\n\n` +
    `💡 *Methodology Note:* Reverse-engineered from official Round 3 closing ranks & State Merit List trends, adjusted for the +810 newly added MBBS seats in 2026 (+110 Govt + +700 Private Cat-A).\n\n` +
    `🔗 Check your allotment simulation: https://kprsnt2.github.io/mSeat/`;
}

function shareWhatsApp() {
  const text = getSummaryText();
  window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
}

function copyOptionsSummary() {
  const text = getSummaryText();
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      showToast('📋 Web Options Summary copied to clipboard!', 'success');
    }).catch(() => {
      showToast('Failed to copy summary', 'error');
    });
  } else {
    showToast('Clipboard copy not supported in browser', 'error');
  }
}

function init() {
  // Pre-render Master Research Table
  renderMasterTable();

  // Build default preference list (Govt first -> Pvt -> Minority last)
  preferences = buildPreferences('categorized');

  // Bind form submission
  const form = document.getElementById('profileForm');
  if (form) form.addEventListener('submit', handleProfileSubmit);

  // Bind filters
  const filterBtns = document.querySelectorAll('.filter-btn');
  filterBtns.forEach(btn => btn.addEventListener('click', function () {
    filterBtns.forEach(b => b.classList.remove('active'));
    this.classList.add('active');
    collegeFilter = this.dataset.filter;
    renderCollegeList();
  }));

  const searchInput = document.getElementById('searchInput');
  if (searchInput) searchInput.addEventListener('input', function () {
    searchQuery = this.value.toLowerCase();
    if (searchQuery.length > 0) toggleCollegeList(true);
    renderCollegeList();
  });

  // Score & Rank inputs sync
  const airInput = document.getElementById('neetAIR');
  const snoInput = document.getElementById('stateSno');
  const scoreInput = document.getElementById('neetScore');
  const scoreSlider = document.getElementById('scoreSlider');

  if (airInput) {
    airInput.addEventListener('input', function () {
      const air = parseInt(this.value);
      if (!isNaN(air) && air > 0) {
        const estScore = estimateScoreFromAIR(air);
        const estSno = estimateStateRank(air);
        if (scoreInput) scoreInput.value = estScore;
        if (scoreSlider) scoreSlider.value = estScore;
        if (snoInput && !snoInput.value) snoInput.placeholder = `Est: ${estSno}`;
        updateScorePreview(estScore, air, estSno);
      }
    });
  }

  if (snoInput) {
    snoInput.addEventListener('input', function () {
      const sno = parseInt(this.value);
      if (!isNaN(sno) && sno > 0) {
        const estAir = estimateAIRFromSno(sno);
        const estScore = estimateScoreFromAIR(estAir);
        if (airInput && !airInput.value) airInput.placeholder = `Est: ${estAir.toLocaleString()}`;
        if (scoreInput) scoreInput.value = estScore;
        if (scoreSlider) scoreSlider.value = estScore;
        updateScorePreview(estScore, estAir, sno);
      }
    });
  }

  if (scoreSlider && scoreInput) {
    scoreSlider.addEventListener('input', function () {
      scoreInput.value = this.value;
      updateScorePreview(this.value);
    });
    scoreInput.addEventListener('input', function () {
      scoreSlider.value = this.value;
      updateScorePreview(this.value);
    });
  }

}

function estimateAIRFromSno(sno) {
  const data = scoreRankData;
  for (let i = 0; i < data.length - 1; i++) {
    if (sno >= data[i].stateSno && sno <= data[i + 1].stateSno) {
      const sDiff = data[i + 1].stateSno - data[i].stateSno;
      if (sDiff === 0) return data[i].rank;
      const rDiff = data[i + 1].rank - data[i].rank;
      const ratio = (sno - data[i].stateSno) / sDiff;
      return Math.round(data[i].rank + ratio * rDiff);
    }
  }
  return Math.round(sno * 32.5);
}

function estimateScoreFromAIR(air) {
  const data = scoreRankData;
  for (let i = 0; i < data.length - 1; i++) {
    if (air >= data[i].rank && air <= data[i + 1].rank) {
      const rDiff = data[i + 1].rank - data[i].rank;
      if (rDiff === 0) return data[i].score;
      const scDiff = data[i].score - data[i + 1].score;
      const ratio = (air - data[i].rank) / rDiff;
      return Math.round(data[i].score - ratio * scDiff);
    }
  }
  return 150;
}

function updateScorePreview(score, customAIR, customSno) {
  const preview = document.getElementById('scorePreview');
  if (!preview) return;
  score = parseInt(score);
  
  const rank = customAIR || (isNaN(score) ? null : estimateRank(score));
  const sno = customSno || (rank ? estimateStateRank(rank) : null);
  const percentile = rank ? Math.max(0, Math.min(100, ((2209000 - rank) / 2209000 * 100))).toFixed(2) : null;
  
  if (!rank) {
    preview.innerHTML = '';
    return;
  }

  preview.innerHTML = `
    <div class="score-preview-content">
      <span class="preview-rank">AIR: <strong>${rank.toLocaleString('en-IN')}</strong></span>
      <span class="preview-rank">State S.No: <strong>${sno.toLocaleString('en-IN')}</strong></span>
      <span class="preview-percentile">Percentile: <strong>${percentile}%</strong></span>
    </div>
  `;
}

function handleProfileSubmit(e) {
  e.preventDefault();

  const name = document.getElementById('studentName')?.value?.trim() || 'Student';
  const airInputVal = parseInt(document.getElementById('neetAIR')?.value);
  const snoInputVal = parseInt(document.getElementById('stateSno')?.value);
  const scoreInputVal = parseInt(document.getElementById('neetScore')?.value);
  const category = document.getElementById('categorySelect')?.value || 'SC_2';
  const gender = document.getElementById('genderSelect')?.value || 'female';
  const localStatus = document.getElementById('localSelect')?.value || 'local';
  const pwd = document.getElementById('pwdCheckbox')?.checked || false;

  let air = null;
  let score = null;
  let stateRank = null;

  if (!isNaN(airInputVal) && airInputVal > 0) {
    air = airInputVal;
    score = !isNaN(scoreInputVal) ? scoreInputVal : estimateScoreFromAIR(air);
    stateRank = !isNaN(snoInputVal) ? snoInputVal : estimateStateRank(air);
  } else if (!isNaN(snoInputVal) && snoInputVal > 0) {
    stateRank = snoInputVal;
    air = estimateAIRFromSno(stateRank);
    score = !isNaN(scoreInputVal) ? scoreInputVal : estimateScoreFromAIR(air);
  } else if (!isNaN(scoreInputVal) && scoreInputVal > 0) {
    score = scoreInputVal;
    air = estimateRank(score);
    stateRank = estimateStateRank(air);
  } else {
    // Default fallback to 134093 AIR / 2363 State S.No / 469 Score if user leaves fields blank
    air = 134093;
    score = 469;
    stateRank = 2363;
  }

  const cutoff = qualifyingCutoffs[category] || 113;
  if (score < cutoff) {
    showToast(`Score ${score} is below qualifying cutoff (${cutoff}) for ${reservationData[category]?.label || category}`, 'error');
    return;
  }

  studentProfile = { name, score, category, gender, localStatus, pwd, customAIR: air, customStateRank: stateRank };
  estimatedAIR = air;

  renderRankResults();
  goToStep(2);
}

function renderRankResults() {
  const { name, score, category, gender, customAIR, customStateRank } = studentProfile;
  const air = customAIR || estimatedAIR || 134093;
  const stateRank = customStateRank || estimateStateRank(air) || 2363;
  const catRank = estimateCategoryRank(air, category, stateRank);
  const percentile = Math.max(0, Math.min(100, ((2209000 - air) / 2209000 * 100))).toFixed(2);

  // Update student info header
  document.getElementById('resultStudentName').textContent = name;
  document.getElementById('resultScore').textContent = score + ' / 720';
  document.getElementById('resultCategory').textContent = reservationData[category]?.label || category;
  document.getElementById('resultGender').textContent = gender === 'female' ? '♀ Female' : '♂ Male';

  // Update rank cards
  document.getElementById('airValue').textContent = air.toLocaleString('en-IN');
  document.getElementById('stateRankValue').textContent = stateRank.toLocaleString('en-IN');
  document.getElementById('catRankValue').textContent = catRank.toLocaleString('en-IN');
  document.getElementById('percentileValue').textContent = percentile + '%';

  // Count eligible colleges
  let govtEligible = 0, pvtEligible = 0;
  govtColleges.forEach(c => { if (isEligible(air, c, category)) govtEligible++; });
  pvtColleges.forEach(c => { if (isEligible(air, c, category)) pvtEligible++; });

  document.getElementById('govtEligibleCount').textContent = govtEligible;
  document.getElementById('pvtEligibleCount').textContent = pvtEligible;
  document.getElementById('totalEligibleCount').textContent = govtEligible + pvtEligible;

  // Render eligibility chart
  renderEligibilityBar(govtEligible, pvtEligible);
}

function renderEligibilityBar(govtCount, pvtCount) {
  const totalGovt = govtColleges.length;
  const totalPvt = pvtColleges.length;
  const govtBar = document.getElementById('govtEligibilityBar');
  const pvtBar = document.getElementById('pvtEligibilityBar');

  if (govtBar) govtBar.style.width = ((govtCount / totalGovt) * 100) + '%';
  if (pvtBar) pvtBar.style.width = ((pvtCount / totalPvt) * 100) + '%';
}

function goToStep(step) {
  // Hide all steps
  document.querySelectorAll('.step-content').forEach(el => {
    el.classList.remove('active');
    el.style.display = 'none';
  });

  // Show target step
  const targetStep = document.getElementById('step' + step);
  if (targetStep) {
    targetStep.style.display = 'block';
    setTimeout(() => targetStep.classList.add('active'), 50);
  }

  // Update step indicators
  document.querySelectorAll('.step-dot').forEach((dot, i) => {
    dot.classList.remove('active', 'completed');
    if (i + 1 < step) dot.classList.add('completed');
    if (i + 1 === step) dot.classList.add('active');
  });

  // Update step connectors
  document.querySelectorAll('.step-connector').forEach((conn, i) => {
    conn.classList.toggle('completed', i + 1 < step);
  });

  currentStep = step;

  // Render college list when going to step 3
  if (step === 3) {
    toggleCollegeList(true);
    renderCollegeList();
  }

  // Scroll to top
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function renderCollegeList() {
  const container = document.getElementById('collegeList');
  if (!container) return;

  const category = studentProfile.category || 'SC_2';
  const air = estimatedAIR || 134093;

  let filtered = [...preferences];

  // Apply type filter
  if (collegeFilter === 'govt') filtered = filtered.filter(c => c.type === 'govt');
  if (collegeFilter === 'pvt') filtered = filtered.filter(c => c.type === 'pvt');

  // Apply search
  if (searchQuery) {
    filtered = filtered.filter(c =>
      c.name.toLowerCase().includes(searchQuery) ||
      c.place.toLowerCase().includes(searchQuery)
    );
  }

  if (filtered.length === 0) {
    container.innerHTML = '<div class="empty-state"><div class="empty-icon">🔍</div><p>No colleges match your search criteria</p></div>';
    return;
  }

  container.innerHTML = filtered.map((college, idx) => {
    const closingRank = getClosingRank(college, category);
    const eligible = air <= closingRank;
    const prefIndex = preferences.indexOf(college);
    const isGovt = college.type === 'govt';
    const fee = isGovt ? college.fee : college.feeA;

    return `
      <div class="college-card ${eligible ? 'eligible' : 'not-eligible'}" data-id="${college.id}">
        <div class="college-rank-badge">#${prefIndex + 1}</div>
        <div class="college-info">
          <div class="college-header">
            <h3 class="college-name">${college.name}</h3>
            <span class="college-type-badge ${isGovt ? 'govt-badge' : 'pvt-badge'}">${isGovt ? 'GOVT' : 'PVT'}</span>
          </div>
          <div class="college-details">
            <span class="college-detail"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg> ${college.place}</span>
            <span class="college-detail"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg> ${college.intake} seats</span>
            <span class="college-detail"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="1" y="4" width="22" height="16" rx="2" ry="2"/><line x1="1" y1="10" x2="23" y2="10"/></svg> ${formatFeeExact(fee)}/yr</span>
          </div>
          <div class="college-ranks">
            <div class="rank-item">
              <span class="rank-label">Your Cat Rank</span>
              <span class="rank-value ${eligible ? 'rank-safe' : 'rank-danger'}">${estimateCategoryRank(air, category).toLocaleString('en-IN')}</span>
            </div>
            <div class="rank-vs">${eligible ? '≤' : '>'}</div>
            <div class="rank-item">
              <span class="rank-label">Closing (${category.replace('_', '-')})</span>
              <span class="rank-value">${closingRank.toLocaleString('en-IN')}</span>
            </div>
            <div class="eligibility-tag ${eligible ? 'tag-eligible' : 'tag-not-eligible'}">
              ${eligible ? '✓ Eligible' : '✗ Not Eligible'}
            </div>
          </div>
        </div>
        <div class="college-actions">
          <button class="move-btn" onclick="movePreference(${prefIndex}, -1)" title="Move Up" ${prefIndex === 0 ? 'disabled' : ''}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="18 15 12 9 6 15"/></svg>
          </button>
          <button class="move-btn" onclick="movePreference(${prefIndex}, 1)" title="Move Down" ${prefIndex === preferences.length - 1 ? 'disabled' : ''}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="6 9 12 15 18 9"/></svg>
          </button>
        </div>
      </div>
    `;
  }).join('');
}

function movePreference(index, direction) {
  const newIndex = index + direction;
  if (newIndex < 0 || newIndex >= preferences.length) return;
  [preferences[index], preferences[newIndex]] = [preferences[newIndex], preferences[index]];
  renderCollegeList();
}

function showAllocationResult() {
  const { category, name, score } = studentProfile;
  const air = estimatedAIR;
  const result = runAllocation(air, category, preferences);

  lastAllocatedResult = result;

  const container = document.getElementById('allocationResult');
  const notAllocatedEl = document.getElementById('notAllocated');
  const allocatedEl = document.getElementById('allocatedSection');

  if (result.allocated) {
    const college = result.college;
    const isGovt = college.type === 'govt';
    const fee = isGovt ? college.fee : college.feeA;

    document.getElementById('allocCollegeName').textContent = college.name;
    document.getElementById('allocCollegePlace').textContent = college.place;
    document.getElementById('allocCollegeType').textContent = isGovt ? 'Government' : 'Private (Cat-A)';
    document.getElementById('allocCollegeFee').textContent = formatFeeExact(fee) + '/year';
    document.getElementById('allocCollegeIntake').textContent = college.intake + ' seats';
    document.getElementById('allocPrefNo').textContent = '#' + result.preferenceNo;
    document.getElementById('allocClosingRank').textContent = result.closingRank.toLocaleString('en-IN');
    document.getElementById('allocCategory').textContent = reservationData[category].label;
    document.getElementById('allocStudentName').textContent = name;
    document.getElementById('allocStudentScore').textContent = score + ' / 720';
    document.getElementById('allocStudentRank').textContent = estimateCategoryRank(air, category).toLocaleString('en-IN') + ' (Cat Rank)';

    // Calculate margin
    const margin = result.closingRank - estimateCategoryRank(air, category);
    document.getElementById('allocMargin').textContent = margin.toLocaleString('en-IN') + ' ranks';
    document.getElementById('allocMargin').className = margin > 50 ? 'margin-safe' : margin > 10 ? 'margin-moderate' : 'margin-tight';

    allocatedEl.style.display = 'block';
    notAllocatedEl.style.display = 'none';

    // Render alternative options (next 5 eligible colleges after allocated one)
    renderAlternatives(result.preferenceNo, air, category);

  } else {
    allocatedEl.style.display = 'none';
    notAllocatedEl.style.display = 'block';
    document.getElementById('notAllocatedScore').textContent = score;
    document.getElementById('notAllocatedRank').textContent = estimateCategoryRank(air, category).toLocaleString('en-IN');
  }

  goToStep(4);
}

function renderAlternatives(allocatedPrefIndex, air, category) {
  const container = document.getElementById('alternativesList');
  if (!container) return;

  let alternatives = [];
  for (let i = allocatedPrefIndex; i < preferences.length && alternatives.length < 5; i++) {
    const college = preferences[i];
    if (isEligible(air, college, category)) {
      const closingRank = getClosingRank(college, category);
      const isGovt = college.type === 'govt';
      const fee = isGovt ? college.fee : college.feeA;
      alternatives.push({ ...college, closingRank, fee, prefNo: i + 1 });
    }
  }

  if (alternatives.length === 0) {
    container.innerHTML = '<p class="no-alternatives">No other eligible colleges in your preference list.</p>';
    return;
  }

  container.innerHTML = alternatives.map(c => `
    <div class="alt-college-card">
      <div class="alt-pref">#${c.prefNo}</div>
      <div class="alt-info">
        <strong>${c.name}</strong>
        <span>${c.place} · ${c.type === 'govt' ? 'Govt' : 'Private'} · ${formatFeeExact(c.fee)}/yr</span>
      </div>
      <div class="alt-rank">Closing: ${c.closingRank.toLocaleString('en-IN')}</div>
    </div>
  `).join('');
}

function resetApp() {
  studentProfile = {};
  estimatedAIR = 0;
  currentStep = 1;
  collegeFilter = 'all';
  searchQuery = '';

  // Reset preferences to original order
  preferences = [
    ...govtColleges.map(c => ({ ...c, type: 'govt' })),
    ...pvtColleges.map(c => ({ ...c, type: 'pvt' }))
  ];

  // Reset form
  const form = document.getElementById('profileForm');
  if (form) form.reset();

  const preview = document.getElementById('scorePreview');
  if (preview) preview.innerHTML = '';

  goToStep(1);
}

// --- Toast Notification ---
function showToast(message, type = 'info') {
  const toast = document.createElement('div');
  toast.className = `toast toast-${type}`;
  toast.innerHTML = `
    <div class="toast-icon">${type === 'error' ? '⚠️' : type === 'success' ? '✅' : 'ℹ️'}</div>
    <div class="toast-message">${message}</div>
  `;
  document.body.appendChild(toast);
  setTimeout(() => toast.classList.add('show'), 50);
  setTimeout(() => {
    toast.classList.remove('show');
    setTimeout(() => toast.remove(), 300);
  }, 3500);
}
// --- Quota Info Modal ---
function showQuotaInfo() {
  const modal = document.getElementById('quotaModal');
  if (modal) {
    pauseBgAnimations();
    modal.classList.add('show');
    document.body.style.overflow = 'hidden';
  }
}

function closeQuotaInfo() {
  const modal = document.getElementById('quotaModal');
  if (modal) {
    modal.classList.remove('show');
    document.body.style.overflow = '';
    resumeBgAnimations();
  }
}

// --- Toggle Name Field ---
function toggleNameField() {
  const nameInput = document.getElementById('studentName');
  const toggleText = document.querySelector('.toggle-text');
  if (nameInput) {
    if (nameInput.classList.contains('name-input-hidden')) {
      nameInput.classList.remove('name-input-hidden');
      nameInput.focus();
      if (toggleText) toggleText.textContent = '- Remove Name';
    } else {
      nameInput.classList.add('name-input-hidden');
      nameInput.value = '';
      if (toggleText) toggleText.textContent = '+ Add Student Name';
    }
  }
}

// ==========================================================================
// AI CHATBOT CONTROLLER (gpt-5.4-mini + MCP Prediction Engine)
// ==========================================================================
const chatHistory = [];

function initAIChatbot() {
  const fab = document.getElementById('ai-chat-fab');
  const drawer = document.getElementById('ai-chat-drawer');
  const closeBtn = document.getElementById('ai-chat-close');
  const sendBtn = document.getElementById('ai-chat-send');
  const inputEl = document.getElementById('ai-chat-input');

  if (!fab || !drawer) return;

  fab.addEventListener('click', () => {
    drawer.classList.toggle('hidden');
    if (!drawer.classList.contains('hidden') && inputEl) {
      inputEl.focus();
    }
  });

  if (closeBtn) {
    closeBtn.addEventListener('click', () => {
      drawer.classList.add('hidden');
    });
  }

  if (sendBtn && inputEl) {
    sendBtn.addEventListener('click', handleChatSubmit);
    inputEl.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        handleChatSubmit();
      }
    });
  }
}

async function handleChatSubmit() {
  const inputEl = document.getElementById('ai-chat-input');
  if (!inputEl) return;

  const query = inputEl.value.trim();
  if (!query) return;

  inputEl.value = '';
  appendChatMessage(query, 'user');

  // Show bot typing placeholder
  const botMsgId = appendChatMessage('⏳ Thinking and running predictions...', 'bot');

  // Gather current form values if present
  const categoryEl = document.getElementById('category');
  const scoreEl = document.getElementById('scoreInput');
  const rankEl = document.getElementById('airRankInput');
  const genderEl = document.querySelector('input[name="gender"]:checked');

  const payload = {
    message: query,
    history: chatHistory,
    category: categoryEl ? categoryEl.value : 'SC_2',
    neetScore: scoreEl ? scoreEl.value : '393',
    neetRank: rankEl ? rankEl.value : '289635',
    gender: genderEl ? genderEl.value : 'Female'
  };

  try {
    const apiEndpoint = window.location.origin.startsWith('http://localhost:3000') || window.location.origin.startsWith('http://127.0.0.1:3000')
      ? '/api/chat'
      : 'http://localhost:3000/api/chat';

    const res = await fetch(apiEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });

    if (res.ok) {
      const data = await res.json();
      updateChatMessage(botMsgId, parseMarkdownToHtml(data.message));
      chatHistory.push({ role: 'user', content: query });
      chatHistory.push({ role: 'assistant', content: data.message });
    } else {
      const fallbackText = getLocalPredictionFallback(query, payload);
      updateChatMessage(botMsgId, fallbackText);
      chatHistory.push({ role: 'user', content: query });
      chatHistory.push({ role: 'assistant', content: fallbackText });
    }
  } catch (err) {
    const fallbackText = getLocalPredictionFallback(query, payload);
    updateChatMessage(botMsgId, fallbackText);
    chatHistory.push({ role: 'user', content: query });
    chatHistory.push({ role: 'assistant', content: fallbackText });
  }
}

function sendQuickPrompt(promptText) {
  const drawer = document.getElementById('ai-chat-drawer');
  if (drawer && drawer.classList.contains('hidden')) {
    drawer.classList.remove('hidden');
  }
  const inputEl = document.getElementById('ai-chat-input');
  if (inputEl) {
    inputEl.value = promptText;
    handleChatSubmit();
  }
}

function appendChatMessage(text, sender) {
  const container = document.getElementById('ai-chat-messages');
  if (!container) return null;

  const msgDiv = document.createElement('div');
  msgDiv.className = `chat-msg ${sender}-msg`;
  const msgId = 'msg-' + Date.now();
  msgDiv.id = msgId;

  const avatar = sender === 'bot' ? '🤖' : '👤';
  msgDiv.innerHTML = `
    <div class="msg-avatar">${avatar}</div>
    <div class="msg-content">${text}</div>
  `;

  container.appendChild(msgDiv);
  container.scrollTop = container.scrollHeight;
  return msgId;
}

function updateChatMessage(msgId, htmlContent) {
  const msgDiv = document.getElementById(msgId);
  if (msgDiv) {
    const contentEl = msgDiv.querySelector('.msg-content');
    if (contentEl) {
      contentEl.innerHTML = htmlContent;
    }
    const container = document.getElementById('ai-chat-messages');
    if (container) container.scrollTop = container.scrollHeight;
  }
}

function getLocalPredictionFallback(query, payload) {
  return processDynamicQuery(query, payload);
}

function processDynamicQuery(query, payload) {
  const qLower = (query || '').toLowerCase();
  
  let conversationText = '';
  if (payload && payload.history) {
    conversationText = payload.history.filter(h => h.role === 'user').map(h => h.content).join(' ');
  }
  conversationText += ' ' + qLower;
  const fullText = conversationText.toLowerCase();

  // 1. Check for Score override in history or query
  let score = parseFloat(payload ? payload.neetScore : 393) || 393;
  const scoreMatches = fullText.match(/(\d{3})\s*(marks|score|pts)?/g);
  if (scoreMatches && scoreMatches.length > 0) {
    const lastMatch = scoreMatches[scoreMatches.length - 1];
    const match = lastMatch.match(/(\d{3})/);
    if (match && parseInt(match[1]) >= 100 && parseInt(match[1]) <= 720) {
      score = parseInt(match[1]);
    }
  }

  // 2. Check for Category override in history or query
  let catKey = (payload ? payload.category : 'SC_2') || 'SC_2';
  catKey = catKey.toUpperCase().replace('-', '_');

  const categories = ['oc', 'ews', 'bc-a', 'bca', 'bc-b', 'bcb', 'bc-c', 'bcc', 'bc-d', 'bcd', 'bc-e', 'bce', 'sc-1', 'sc1', 'sc-2', 'sc2', 'sc-3', 'sc3', 'st'];
  let latestCatIndex = -1;
  categories.forEach(cat => {
    const idx = fullText.lastIndexOf(cat);
    if (idx > latestCatIndex) {
      latestCatIndex = idx;
      if (cat === 'oc') catKey = 'OC';
      else if (cat === 'ews') catKey = 'EWS';
      else if (cat === 'bc-a' || cat === 'bca') catKey = 'BC_A';
      else if (cat === 'bc-b' || cat === 'bcb') catKey = 'BC_B';
      else if (cat === 'bc-c' || cat === 'bcc') catKey = 'BC_C';
      else if (cat === 'bc-d' || cat === 'bcd') catKey = 'BC_D';
      else if (cat === 'bc-e' || cat === 'bce') catKey = 'BC_E';
      else if (cat === 'sc-1' || cat === 'sc1') catKey = 'SC_1';
      else if (cat === 'sc-2' || cat === 'sc2') catKey = 'SC_2';
      else if (cat === 'sc-3' || cat === 'sc3') catKey = 'SC_3';
      else if (cat === 'st') catKey = 'ST';
    }
  });

  // 3. Intent: Comparison (e.g. "Mamata Bachupally vs CMR Medchal" or "compare X and Y")
  if (qLower.includes(' vs ') || qLower.includes('versus') || qLower.includes('compare')) {
    const all = [...(typeof govtColleges !== 'undefined' ? govtColleges : []), ...(typeof pvtColleges !== 'undefined' ? pvtColleges : [])];
    const matches = all.filter(c => qLower.includes(c.name.toLowerCase().split(' ')[0]) || qLower.includes(c.place.toLowerCase()));
    if (matches.length >= 2) {
      const colA = matches[0];
      const colB = matches[1];
      const rankA = colA.knownRanks?.[catKey] || colA.knownRanks?.SC || 'N/A';
      const rankB = colB.knownRanks?.[catKey] || colB.knownRanks?.SC || 'N/A';
      return `
        <h3>⚖️ College Comparison (${catKey} Category)</h3>
        <table>
          <thead>
            <tr><th>Metric</th><th>${colA.name}</th><th>${colB.name}</th></tr>
          </thead>
          <tbody>
            <tr><td><strong>Place</strong></td><td>${colA.place}</td><td>${colB.place}</td></tr>
            <tr><td><strong>Type</strong></td><td>${colA.type === 'govt' ? 'GOVT' : 'PVT-A'}</td><td>${colB.type === 'govt' ? 'GOVT' : 'PVT-A'}</td></tr>
            <tr><td><strong>Intake</strong></td><td>${colA.intake} seats</td><td>${colB.intake} seats</td></tr>
            <tr><td><strong>${catKey} Cutoff AIR</strong></td><td>${typeof rankA === 'number' ? rankA.toLocaleString() : rankA}</td><td>${typeof rankB === 'number' ? rankB.toLocaleString() : rankB}</td></tr>
          </tbody>
        </table>
        <p>💡 <em>Comparative prediction based on official closing cutoffs.</em></p>
      `;
    }
  }

  // 4. Intent: Seat Expansion Stats
  if (qLower.includes('seat') || qLower.includes('expansion') || qLower.includes('stats') || qLower.includes('increase')) {
    return `
      <h3>📊 2026 Telangana MBBS Seat Expansion Stats</h3>
      <p><strong>Government Medical Colleges Seat Increases (+110 seats)</strong>:</p>
      <ul>
        <li>GMC Mahabubnagar: +25 seats (175 ➔ 200)</li>
        <li>GMC Nizamabad: +30 seats (120 ➔ 150)</li>
        <li>GMC Siddipet: +25 seats (175 ➔ 200)</li>
        <li>RIMS Adilabad: +30 seats (120 ➔ 150)</li>
      </ul>
      <p><strong>Private Medical Colleges Seat Increases (+350 seats)</strong>:</p>
      <ul>
        <li>Bhaskar Medical College: +50 seats (150 ➔ 200)</li>
        <li>Maheshwara Medical College: +100 seats (150 ➔ 250)</li>
        <li>Malla Reddy IMS: +50 seats (200 ➔ 250)</li>
        <li>Mamata Academy Bachupally: +50 seats (150 ➔ 200)</li>
        <li>MNR Sangareddy: +100 seats (150 ➔ 250)</li>
      </ul>
      <p><strong>New Colleges</strong>: Raja Rajeshwari Institute of Medical Sciences (Girls) - 150 Seats</p>
    `;
  }

  // 5. Intent: Dynamic Admission Prediction for the extracted score & category
  const air = typeof estimateRank === 'function' ? estimateRank(score) : 289635;
  const stateSno = typeof estimateStateRank === 'function' ? estimateStateRank(air) : 8902;

  const gList = typeof govtColleges !== 'undefined' ? govtColleges : [];
  const pList = typeof pvtColleges !== 'undefined' ? pvtColleges : [];

  const all = [
    ...gList.map(c => ({ ...c, typeText: 'GOVT' })),
    ...pList.map(c => ({ ...c, typeText: 'PVT-A' }))
  ];

  let eligibleGmc = [];
  let eligiblePvt = [];
  let borderline = [];

  all.forEach(c => {
    const cutoff = c.knownRanks?.[catKey] || c.knownRanks?.SC || c.knownRanks?.OC;
    if (!cutoff || cutoff === 9999999) return;
    const diff = cutoff - air;
    const item = { name: c.name, place: c.place, type: c.typeText, cutoffRank: cutoff, safetyMargin: diff };

    if (diff >= 0) {
      if (c.typeText === 'GOVT') eligibleGmc.push(item);
      else eligiblePvt.push(item);
    } else if (diff >= -30000) {
      borderline.push(item);
    }
  });

  eligibleGmc.sort((a, b) => a.cutoffRank - b.cutoffRank);
  eligiblePvt.sort((a, b) => a.cutoffRank - b.cutoffRank);
  borderline.sort((a, b) => b.cutoffRank - a.cutoffRank);

  let html = `<h3>🤖 mSeat AI Admission Counselor</h3>`;
  html += `<p>Query: <em>"${query}"</em></p>`;
  html += `<p><strong>Evaluated Profile</strong>: Score <strong>${score} Marks</strong> | Est. AIR <strong>${air.toLocaleString()}</strong> | Est. State S.No <strong>#${stateSno.toLocaleString()}</strong> | Category <strong>${catKey}</strong></p>`;

  if (eligibleGmc.length > 0) {
    html += `<h4>🏛️ Eligible Government Medical Colleges (${eligibleGmc.length}):</h4><ul>`;
    eligibleGmc.slice(0, 5).forEach(c => {
      html += `<li><strong>${c.name}</strong> (${c.place}) - Cutoff AIR ${c.cutoffRank.toLocaleString()} (+${c.safetyMargin.toLocaleString()} ranks safe)</li>`;
    });
    html += `</ul>`;
  } else {
    html += `<p>ℹ️ <em>No Government Medical Colleges clear the cutoff at ${score} marks for ${catKey} category.</em></p>`;
  }

  if (eligiblePvt.length > 0) {
    html += `<h4>🏥 Eligible Private A-Category Colleges (${eligiblePvt.length} Total):</h4><ul>`;
    eligiblePvt.slice(0, 6).forEach(c => {
      html += `<li><strong>${c.name}</strong> (${c.place}) - Cutoff AIR ${c.cutoffRank.toLocaleString()} (+${c.safetyMargin.toLocaleString()} ranks safe)</li>`;
    });
    html += `</ul>`;
  }

  if (borderline.length > 0) {
    html += `<h4>⚡ Borderline / Upgradation Possibilities:</h4><ul>`;
    borderline.slice(0, 3).forEach(c => {
      html += `<li><strong>${c.name}</strong> (${c.type}) - Cutoff AIR ${c.cutoffRank.toLocaleString()} (Short by ${Math.abs(c.safetyMargin).toLocaleString()} ranks)</li>`;
    });
    html += `</ul>`;
  }

  html += `<p>⚡ <em>Dynamic prediction calculated using mSeat 2026 Merit Engine.</em></p>`;
  return html;
}

function parseMarkdownToHtml(markdown) {
  if (!markdown) return '';
  let html = markdown
    .replace(/^### (.*$)/gim, '<h3>$1</h3>')
    .replace(/^#### (.*$)/gim, '<h4>$1</h4>')
    .replace(/^## (.*$)/gim, '<h2>$1</h2>')
    .replace(/^\> (.*$)/gim, '<blockquote>$1</blockquote>')
    .replace(/\*\*(.*?)\*\*/gim, '<strong>$1</strong>')
    .replace(/\*(.*?)\*/gim, '<em>$1</em>')
    .replace(/`(.*?)`/gim, '<code>$1</code>')
    .replace(/\n\n/gim, '<br><br>');
  return html;
}

// --- Initialize on DOM ready ---
document.addEventListener('DOMContentLoaded', () => {
  init();
  initAIChatbot();
});


// AUTOFILL LOGIC based on S.No
document.addEventListener('DOMContentLoaded', () => {
  const snoInput = document.getElementById('stateSno');
  if (snoInput) {
    snoInput.addEventListener('input', (e) => {
      const sno = parseInt(e.target.value);
      if (sno && snoToCatRanks2026[sno]) {
        const data = snoToCatRanks2026[sno];
        
        const airInput = document.getElementById('neetAIR');
        const scoreInput = document.getElementById('neetScore');
        const catSelect = document.getElementById('category');
        const genderSelect = document.getElementById('gender');
        
        if (airInput) { airInput.value = data.air; airInput.style.borderColor = '#10b981'; }
        if (scoreInput) { scoreInput.value = data.score; scoreInput.style.borderColor = '#10b981'; }
        
        if (catSelect) {
          // data.cat is like "OC", "BCA", "SC2"
          let mappedCat = data.cat;
          if (mappedCat.length === 3 && (mappedCat.startsWith('BC') || mappedCat.startsWith('SC'))) {
             mappedCat = mappedCat.substring(0,2) + '_' + mappedCat.substring(2);
          }
          if (data.ews && mappedCat === 'OC') {
             mappedCat = 'EWS';
          }
          catSelect.value = mappedCat;
          catSelect.style.borderColor = '#10b981';
        }
        
        if (genderSelect) {
          genderSelect.value = data.gender;
          genderSelect.style.borderColor = '#10b981';
        }
      }
    });
  }
});


// 1-Click Quick Predict Logic
function quickPredict() {
  const snoInput = document.getElementById('stateSno').value;
  const airInput = document.getElementById('neetAIR').value;
  
  if (!snoInput && !airInput) {
    alert("Please enter either your State S.No or NEET AIR for quick predict.");
    return;
  }

  if (snoInput && !airInput && typeof snoToCatRanks2026 !== 'undefined' && snoToCatRanks2026[snoInput]) {
    const data = snoToCatRanks2026[snoInput];
    document.getElementById('neetAIR').value = data.air;
    document.getElementById('neetScore').value = data.score;
    let mappedCat = data.cat;
    if (mappedCat.length === 3 && (mappedCat.startsWith('BC') || mappedCat.startsWith('SC'))) {
       mappedCat = mappedCat.substring(0,2) + '_' + mappedCat.substring(2);
    }
    if (data.ews && mappedCat === 'OC') {
       mappedCat = 'EWS';
    }
    document.getElementById('categorySelect').value = mappedCat || document.getElementById('categorySelect').value;
    document.getElementById('genderSelect').value = data.gender || document.getElementById('genderSelect').value;
  }

  const form = document.getElementById('profileForm');
  if(!form.checkValidity()) {
    form.reportValidity();
    return;
  }

  // Set up globals manually so we don't conflict with handleProfileSubmit timings
  const category = document.getElementById('categorySelect').value;
  const rawAir = parseInt(document.getElementById('neetAIR').value);
  const sno = parseInt(document.getElementById('stateSno').value);
  const score = parseInt(document.getElementById('neetScore').value);
  
  const air = isNaN(rawAir) ? estimateRank(score) : rawAir;
  const stateRank = isNaN(sno) ? estimateStateRank(air) : sno;
  
  studentProfile = {
    name: document.getElementById('studentName')?.value?.trim() || 'Student',
    score: score,
    category: category,
    gender: document.getElementById('genderSelect').value,
    localStatus: 'local',
    pwd: false,
    customAIR: air,
    customStateRank: stateRank
  };
  estimatedAIR = air;
  
  document.getElementById('prefType').value = 'mixed';
  
  const combinedColleges = [...govtColleges, ...pvtColleges].sort((a, b) => getClosingRank(a, category) - getClosingRank(b, category));
  const result = runAllocation(air, category, combinedColleges);
  
  if (result.allocated) {
    document.getElementById('allocSuccess').style.display = 'block';
    document.getElementById('allocFailure').style.display = 'none';
    document.getElementById('allocCollegeName').textContent = result.college.name;
    document.getElementById('allocCollegePlace').textContent = result.college.place;
    document.getElementById('allocCollegeType').textContent = result.college.type === 'govt' ? 'Government Medical College' : 'Private Medical College (Cat-A)';
    document.getElementById('allocClosingRank').textContent = result.closingRank.toLocaleString('en-IN');
    const fee = result.college.fee || (result.college.type === 'govt' ? 29000 : 60000);
    document.getElementById('allocCollegeFee').textContent = '₹' + fee.toLocaleString('en-IN') + ' / year';
    document.getElementById('allocStudentRank').textContent = estimateCategoryRank(air, category).toLocaleString('en-IN') + ' (Cat Rank)';
    
    const margin = result.closingRank - estimateCategoryRank(air, category);
    document.getElementById('allocMarginVal').textContent = margin.toLocaleString('en-IN');
    document.getElementById('allocMargin').className = margin > 50 ? 'margin-safe' : margin > 10 ? 'margin-moderate' : 'margin-tight';
  } else {
    document.getElementById('allocSuccess').style.display = 'none';
    document.getElementById('allocFailure').style.display = 'block';
    document.getElementById('notAllocatedRank').textContent = estimateCategoryRank(air, category).toLocaleString('en-IN');
  }
  
  goToStep(4);
}
